insert into initiatives(id,rank,name,concept,status,owner_name,budget_inr,expected_cash_inr,kpi_name,kpi_unit,direction,scale_threshold,stop_threshold,decision_rule,start_date,end_date,is_simulated) values (1,1,'Sponsor-gets-sponsor referral engine','Every confirmed partner introduces two peer brands in exchange for bonus inventory. Warm channels won 24 of 25 source opportunities; cold channels won none.','testing','Riya Kapoor',40000,720000,'Intro-to-meeting rate within 7 days','%','higher_is_better',50,25,'Scale at >=50% after 2 weeks; change the ask script at 25-50%; stop below 25%.','2025-03-17','2025-04-06',true);
insert into initiatives(id,rank,name,concept,status,owner_name,budget_inr,expected_cash_inr,kpi_name,kpi_unit,direction,scale_threshold,stop_threshold,decision_rule,start_date,end_date,is_simulated) values (2,2,'Cash-first deal terms','Invoice at signing, 50% advance, 3% discount for full prepayment, T-21 cash checkpoint. Converts confirmed value into collected cash; one source deal reneged after confirmation.','testing','Nisha Rao',30000,310000,'% of confirmed value with advance received','%','higher_is_better',60,30,'Scale at >=60%; at 30-60% add founder-to-founder follow-up; below 30% relax to 30% advance.','2025-03-17','2025-04-10',true);
insert into initiatives(id,rank,name,concept,status,owner_name,budget_inr,expected_cash_inr,kpi_name,kpi_unit,direction,scale_threshold,stop_threshold,decision_rule,start_date,end_date,is_simulated) values (3,3,'Rescue leaked and stalled demand','Open deals for qualified brands that never got an opportunity, and re-route stalled cold deals through a warm re-introduction or close them.','testing','Meera Iyer',10000,300000,'% of rescued brands with a meeting booked in 10 days','%','higher_is_better',40,15,'Scale at >=40%; 15-40% change the intro source; below 15% close the stalled deals.','2025-03-17','2025-04-03',true);
insert into initiatives(id,rank,name,concept,status,owner_name,budget_inr,expected_cash_inr,kpi_name,kpi_unit,direction,scale_threshold,stop_threshold,decision_rule,start_date,end_date,is_simulated) values (4,4,'Proof-based packages using attendee data','Tiered packages priced on verified outcomes (sampling to verified attendees, leads captured), using the sponsor-to-attendee campaign links.','planned','Nisha Rao',25000,350000,'Average proposal value vs Rs 93K baseline','INR','higher_is_better',110000,85000,'Scale if average proposal >= Rs 1.1L with no drop in acceptance; stop if below Rs 85K.','2025-03-24','2025-04-10',true);
insert into initiatives(id,rank,name,concept,status,owner_name,budget_inr,expected_cash_inr,kpi_name,kpi_unit,direction,scale_threshold,stop_threshold,decision_rule,start_date,end_date,is_simulated) values (5,5,'Category-exclusive anchor tender','One structured competitive pitch for title or category exclusivity among the categories that convert best (food and beverage, mobility).','testing','Riya Kapoor',20000,720000,'Brands submitting a bid by the deadline','brands','higher_is_better',3,2,'Scale with 3+ bids; with 2 bids negotiate bilaterally; under 2 drop the tender and sell the slot as a standard tier.','2025-03-20','2025-04-03',true);
insert into initiatives(id,rank,name,concept,status,owner_name,budget_inr,expected_cash_inr,kpi_name,kpi_unit,direction,scale_threshold,stop_threshold,decision_rule,start_date,end_date,is_simulated) values (6,null,'Scale cold email outreach','Rejected: 507 touches across 91 brands produced 11 opportunities and 0 confirmed partnerships.','rejected',null,0,0,null,null,'higher_is_better',null,null,'Rejected on source evidence.',null,null,true);
